import {specialModel} from './special-models.js';
import * as THREE from 'three';
const box=new THREE.BoxGeometry(1,1,1),ball=new THREE.SphereGeometry(1,12,8),tube=new THREE.CylinderGeometry(1,1,1,12),m={dark:new THREE.MeshStandardMaterial({color:0x273d39}),metal:new THREE.MeshStandardMaterial({color:0x9eb7b8,metalness:.5,roughness:.4}),olive:new THREE.MeshStandardMaterial({color:0x719963}),wood:new THREE.MeshStandardMaterial({color:0xc89b59}),blue:new THREE.MeshStandardMaterial({color:0x56bdf2,emissive:0x123755})};
function part(g,geo,mat,p,s,rx=0){let o=new THREE.Mesh(geo,mat);o.position.set(...p);o.scale.set(...s);o.rotation.x=rx;o.castShadow=true;g.add(o);return o;}
export function weaponModel(kind,boost=false){if(['mech','helicopter','mega'].includes(kind))return specialModel(kind);let g=new THREE.Group();g.name=kind;let metal=boost?m.blue:m.metal;if(kind==='uzi'){part(g,box,m.dark,[0,0,0],[.25,.35,.9]);part(g,tube,metal,[0,.03,-.65],[.10,.55,.10],Math.PI/2);part(g,box,m.dark,[0,-.3,.13],[.18,.45,.22]);part(g,box,metal,[0,-.3,-.17],[.15,.4,.18]);part(g,box,m.wood,[0,.12,.63],[.23,.12,.42]);}else if(kind==='grenade'){part(g,ball,m.olive,[0,-.03,0],[.3,.4,.3]);part(g,box,metal,[0,.4,0],[.18,.15,.18]);part(g,box,m.dark,[.16,.20,0],[.1,.53,.12]);let ring=new THREE.Mesh(new THREE.TorusGeometry(.13,.035,5,10),metal);ring.position.set(-.15,.43,0);g.add(ring);}else if(kind==='bazooka'){part(g,tube,m.olive,[0,0,-.17],[.28,1.9,.28],Math.PI/2);part(g,tube,metal,[0,0,-1.13],[.34,.12,.34],Math.PI/2);part(g,tube,m.dark,[0,0,-1.2],[.23,.13,.23],Math.PI/2);part(g,box,m.wood,[0,-.35,.25],[.18,.5,.25]);part(g,box,m.dark,[.18,.32,-.1],[.12,.3,.3]);}else if(kind==='tank'){part(g,box,m.olive,[0,.6,0],[2.6,.9,3]);for(let x of [-1.3,1.3])part(g,box,m.dark,[x,.35,0],[.6,.7,3.3]);part(g,tube,m.olive,[0,1.35,0],[.8,.55,.8]);part(g,tube,metal,[0,1.5,-1.2],[.13,2.3,.13],Math.PI/2);}else{part(g,ball,kind==='health'?m.wood:metal,[0,0,0],[.35,.35,.35]);}return g;}
